class Solution:
    def maxSumDistinctTriplet(self, x, y):
        best = {}
        for a, b in zip(x, y):
            if b > best.get(a, 0):
                best[a] = b
        if len(best) < 3:
            return -1
        return sum(sorted(best.values())[-3:])

