class Solution {
    public int maxSumDistinctTriplet(int[] x, int[] y) {
        Map<Integer, Integer> best = new HashMap<>();
        for (int i = 0; i < x.length; i++)
            best.merge(x[i], y[i], Math::max);
        if (best.size() < 3) return -1;
        int a = 0, b = 0, c = 0;
        for (int v : best.values()) {
            if (v > a) { c = b; b = a; a = v; }
            else if (v > b) { c = b; b = v; }
            else if (v > c) c = v;
        }
        return a + b + c;
    }
}

