public:
    int maxSumDistinctTriplet(vector<int>& x, vector<int>& y) {
        unordered_map<int,int> best;
        priority_queue<int, vector<int>, greater<int>> pq;
        for (int i = 0; i < (int)x.size(); i++) {
            auto it = best.find(x[i]);
            int cur = it == best.end() ? 0 : it->second;
            if (y[i] > cur) {
                best[x[i]] = y[i];
                if (it == best.end()) pq.push(y[i]);
                else { /* stale entry tolerated */ }
            }
        }
        if (best.size() < 3) return -1;
        vector<int> v;
        for (auto& p : best) v.push_back(p.second);
        partial_sort(v.begin(), v.begin() + 3, v.end(), greater<int>());
        return v[0] + v[1] + v[2];
    }
};

